const records=window.RESEARCH;
const researchHref=r=>r.earlyGroup?`#undergraduate/${r.earlyGroup}`:`#work/${r.id}`;
const scholar='https://scholar.google.com/citations?user=0V7T8KIAAAAJ&hl=en';
const main=document.getElementById('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tag=t=>`<span class="tag">${esc(t)}</span>`;
const pending=(title,text)=>`<div class="pending"><strong>${title}</strong><p>${text}</p></div>`;
function artwork(i){const content=[`<path d="M45 30 130 55 215 25M45 30 65 95 130 55 210 95 215 25M65 95 210 95"/><g fill="#60dcc7"><circle cx="45" cy="30" r="6"/><circle cx="65" cy="95" r="6"/><circle cx="130" cy="55" r="9"/><circle cx="215" cy="25" r="6"/><circle cx="210" cy="95" r="6"/></g>`,`<rect x="35" y="30" width="45" height="65" rx="6"/><rect x="110" y="20" width="45" height="75" rx="6"/><rect x="185" y="40" width="45" height="55" rx="6"/><path d="M45 50h25m-25 15h25m50-25h25m-25 15h25m50 5h25m-25 15h25"/>`,`<path d="M25 95C65 90 60 30 100 40S145 90 175 45 220 45 250 20"/><path stroke-dasharray="4 6" d="M25 100C70 100 65 50 100 50S145 100 175 55 220 65 250 40"/>`][i%3];return `<div class="art" aria-hidden="true"><svg viewBox="0 0 280 120" fill="none" stroke="#77bff0" stroke-width="2">${content}</svg></div>`;}
function card(r,i){return `<article class="card">${artwork(i)}<div class="card-body"><div class="card-meta"><span>${r.year} · ${r.shortVenue||(r.id==='gwnet'?'ESWA':r.id==='ode'?'Information Fusion':'IEEE TIM')}</span><span>${r.kind||'论文'}</span></div><h3>${r.short}</h3><p>${r.summary}</p><a class="button" href="#work/${r.id}">阅读研究档案</a><div class="scope">${r.period||r.sequence||r.relation||"研究时期待补充"}${r.role?' · '+r.role:''}</div></div></article>`;}
function overview(){main.innerHTML=`<section class="hero"><div class="eyebrow">Shifan Chen / Zhejiang University</div><h1>理解复杂过程，<br><span class="gradient">记录研究如何发生。</span></h1><p class="lead">从生化过程建模到研究工具与数据，展示每项工作的核心问题、方法选择，以及共同完成研究的人。</p><div class="links"><a class="button primary" href="#work/gwnet">从 GWNet 开始了解</a><a class="button" href="${scholar}">Google Scholar</a><a class="button" href="https://github.com/cynara517">GitHub</a></div></section><div class="themes"><section class="theme"><span class="eyebrow">Modeling</span><h3>理解生化过程的动态变化</h3><p>关注变量关联、时间变化与过程预测。以 GWNet 和 ODE-aware 学习工作作为阅读入口。</p></section><section class="theme"><span class="eyebrow">Accessibility</span><h3>让研究更容易被开展</h3><p>围绕复杂批次过程的 AI 研究可及性，以及研究数据和工具的组织。</p></section><section class="theme"><span class="eyebrow">Collaboration</span><h3>记录共同完成的工作</h3><p>把具体贡献放回课题背景，说明每一位参与者如何帮助工作向前推进。</p></section></div><div class="section-head"><h2>精选研究</h2><p>问题 · 洞察 · 贡献 · 研究历程</p></div><div class="cards">${records.filter(r=>r.selected).map(card).join('')}</div>${undergraduateFeature()}<div class="section-head"><h2>成果中的时间线</h2><p>按成果年份整理</p></div><div class="journey"><div class="year-row"><div class="year">2026</div><p><strong>研究可及性、动力学预测与过程安全</strong><br>Accessible AI · ODE-aware step-coupled learning · Bio-Process Safeguard</p></div><div class="year-row"><div class="year">2025</div><p><strong>过程建模与合作研究</strong><br>Gate-based GWNet · 生物制药软测量 · 多智能体任务卸载</p></div><div class="year-row"><div class="year">2022</div><p><strong>轨迹追踪与识别方法</strong><br><a href="#undergraduate/modeling">Asian giant hornet trajectory tracking · Face recognition</a></p></div><div class="year-row"><div class="year">2021</div><p><strong>传感与跨领域研究</strong><br><a href="#undergraduate">织物传感器睡眠检测 · 运动干预 · 马拉松评价体系</a></p></div></div><div class="section-head"><h2>研究之外，也建设工具</h2></div><section class="journey"><h3>ChemWatch · 化学数据观测站</h3><p class="muted">浏览化学数据集与 benchmark，追踪公开研究资源。</p><a class="button" href="../chemwatch.html">访问 ChemWatch</a></section>`;}
function publications(){main.innerHTML=`<div class="page-top"><div class="eyebrow">Publications & projects</div><h1>全部研究成果</h1><p class="muted">${records.length} 项论文与会议成果，记录研究问题、方法与背后的经历。本科阶段的五项工作按主题合并展示。</p></div><div class="filters"><input id="search" aria-label="搜索论文" placeholder="搜索题目、作者或期刊"><select id="topic" aria-label="按研究方向筛选"><option value="">全部方向</option>${[...new Set(records.map(r=>r.topic))].map(t=>`<option value="${esc(t)}">${t}</option>`).join('')}</select></div><p id="count" class="muted small" aria-live="polite"></p><div id="results"></div>`;const render=()=>{const q=document.getElementById('search').value.trim().toLowerCase(),topic=document.getElementById('topic').value;const list=records.filter(r=>(!topic||r.topic===topic)&&[r.title,r.short,r.authors,r.venue,r.topic,...[r.short,r.topic].map(x=>window.paperEnglish?.[x]||'')].join(' ').toLowerCase().includes(q)).sort((a,b)=>b.year-a.year);document.getElementById('count').textContent=`显示 ${list.length} / ${records.length} 项`;const later=list.filter(r=>!r.earlyGroup),early=list.filter(r=>r.earlyGroup);document.getElementById('results').innerHTML=later.map(r=>`<article class="pub"><div class="year">${r.year}</div><div><h2><a href="${researchHref(r)}">${r.title}</a></h2><p>${r.authors}</p><p>${r.venue}</p>${tag(r.topic)}</div></article>`).join('')+(early.length?`<section class="early-publications"><div class="section-head"><h2><a href="#undergraduate">本科探索 · 研究的起点</a></h2><p>${early.length} 项成果</p></div><div class="early-groups">${[['sensors','传感器与交叉研究'],['modeling','数学建模相关研究'],['sports','体育相关研究']].map(([id,label])=>{const items=early.filter(r=>r.earlyGroup===id).sort((a,b)=>['sleep','hornets','face','marathon','exercise'].indexOf(a.id)-['sleep','hornets','face','marathon','exercise'].indexOf(b.id));return items.length?`<div><h3><a href="#undergraduate/${id}">${label}</a></h3>${items.map(r=>`<p><a href="${researchHref(r)}">${esc(r.short)}</a><br><span class="small muted">${r.year} · ${esc(r.venue)}</span></p>`).join('')}</div>`:'';}).join('')}</div></section>`:'')||'<p class="empty">没有匹配的成果，请尝试其他关键词。</p>';window.localizePapers?.();};document.getElementById('search').addEventListener('input',render);document.getElementById('topic').addEventListener('change',render);render();}
function detail(id){const r=records.find(x=>x.id===id);if(r?.earlyGroup){undergraduate();return;}if(!r){main.innerHTML='<div class="page-top"><h1>未找到研究档案</h1><a href="#publications">返回全部成果</a></div>';return;}const full=id==='gwnet';const accessibleWork=id==='accessible';const odeWork=id==='ode';const safeguardWork=id==='safeguard';main.innerHTML=`<div class="page-top"><a class="small" href="#publications">全部成果 / 研究档案</a><h1>${r.short||r.title}</h1><p class="muted">${r.title}</p><p class="small muted">${r.authors}</p></div><div class="detail-grid"><article>${full?gwnet():accessibleWork?accessible():odeWork?ode():safeguardWork?safeguard():`<section><h2>研究方向</h2><p>${r.summary}</p></section>`}<section id="sources"><h2>${safeguardWork?"项目与代码":"阅读论文"}</h2><p><a href="${r.source||scholar}">${safeguardWork?"Bio-Process Safeguard · GitHub":r.source?r.title:'Google Scholar 论文条目'}</a></p></section></article><aside class="facts"><span class="eyebrow">Research record</span><dl><dt>研究方向</dt><dd>${r.topic}</dd><dt>成果来源 / 年份</dt><dd>${r.venue}<br>${r.year}</dd>${safeguardWork?`<dt>研究关联</dt><dd><a href="#work/accessible">${r.relation}</a></dd>`:odeWork?`<dt>研究序列</dt><dd>${r.sequence}</dd>`:`<dt>研究时期</dt><dd>${r.period||"合作研究"}</dd>`}<dt>发表状态</dt><dd>${r.status||(full||accessibleWork||odeWork?'已发表':'已发表')}</dd>${accessibleWork||odeWork||safeguardWork?'':`<dt>个人贡献</dt><dd>${r.role||'合作作者'}</dd>`}</dl><nav aria-label="页内目录">${full?'<a href="#work/gwnet/origin">灵感如何发生</a><a href="#work/gwnet/problem">问题与洞察</a><a href="#work/gwnet/contribution">方法与主要结果</a><a href="#work/gwnet/people">导师与合作者</a><a href="#work/gwnet/journey">研究与审稿</a>':accessibleWork?'<a href="#work/accessible/origin">从上一项工作出发</a><a href="#work/accessible/problem">Accessible 的含义</a><a href="#work/accessible/contribution">方法与研究产出</a><a href="#work/accessible/journey">回应方法学质疑</a>':odeWork?'<a href="#work/ode/origin">从微生物的节奏出发</a><a href="#work/ode/problem">机理与工业过程的距离</a><a href="#work/ode/control">世界模型与控制理论</a><a href="#work/ode/insight">研究动机</a><a href="#work/ode/journey">重新送审与发表</a><a href="#work/ode/reflection">交叉研究的写作反思</a>':safeguardWork?'<a href="#work/safeguard/origin">从数据共享继续出发</a><a href="#work/safeguard/problem">数据可信的另一层含义</a><a href="#work/safeguard/contribution">方法与主要结果</a>':''}<a href="#work/${id}/sources">${safeguardWork?"项目与代码":"阅读论文"}</a></nav></aside></div>`;}
function gwnet(){return `<section id="origin"><span class="eyebrow">Where the idea began</span><h2>从交通路网，看见发酵过程中的关系</h2><p>这是我博士一年级的第一项研究，起于与东阳光制药联合的生物发酵场景。观察交通数据时，我注意到两件事：道路连接形成路网，路网上的流量又随时间变化。这让我想到，发酵过程中不同传感器之间的关系，也可以用网络来理解；随着发酵阶段变化，变量的动态特征也会改变。</p><div class="takeaway"><span class="tag">想法的起点</span><p>不同传感器之间的关系，何尝不是一种“路网”？</p></div><p>这个类比推动我把交通预测中的时空建模思路带入生物发酵，开展后续实践。</p><div class="analogy"><div><span class="eyebrow">交通中的观察</span><h3>路网连接 · 时变流量</h3><p>关注结构关系与随时间变化的特征。</p></div><div><span class="eyebrow">发酵中的研究问题</span><h3>传感器关联 · 阶段变化</h3><p>把变量关系和发酵阶段的动态变化放在一起思考。</p></div></div><figure class="paper-figure"><a href="assets/gwnet-figure-1.jpg" target="_blank" rel="noopener" aria-label="打开论文图 1 原图"><img src="assets/gwnet-figure-1.jpg" width="706" height="518" alt="GWNet 论文图 1：以发酵罐为中心，展示底物控制、温度控制、pH 控制和传感器测量中的过程变量。" loading="lazy"></a><figcaption>论文图 1 · 发酵过程及变量示意：底物、温度、pH 控制与传感器测量共同构成了理解过程关系的直观背景。点击查看原图。</figcaption></figure><details><summary>课题背景与支持</summary><p>这项研究依托国家重点研发计划相关课题，在与东阳光制药的合作中开展。真实的红霉素生产过程为我们提供了研究场景，DYG 数据也来自这一生产过程。刘兴高教授主持的“生物过程实时智能诊断、分析与优化控制”项目，是这一研究方向的重要背景。</p><p>感谢国家自然科学基金、浙江省重点研发计划和浙江大学 NGICS 平台对本项工作的支持。</p><p class="small">论文资助：国家自然科学基金 62073288、12075212、12105246、11975207；浙江省重点研发计划 2020C01038、2021C01032。</p></details></section>
<section id="problem"><span class="eyebrow">The question</span><h2>发酵过程在变化，模型该保留什么信息？</h2><p>发酵罐中的多个变量相互关联，这些关系又会随发酵阶段变化。我们希望模型既能捕捉发酵的整体规律，也能动态筛选当前阶段对预测有用的信息。</p><div class="takeaway"><span class="tag">核心 insight</span><p>建模变量之间的关系，还需要适应不同阶段的信息变化。</p></div><div class="flow"><div><b>输入</b><span>多变量发酵时间序列</span></div><div><b>关系与筛选</b><span>图结构学习 + 时间门控</span></div><div><b>输出</b><span>多输出过程预测</span></div></div></section>
<section id="contribution"><span class="eyebrow">My contribution</span><h2>同时学习过程规律与动态变化</h2><p>我们提出 Gate-based GWNet，将图结构学习和时间门控结合，面向生物发酵过程进行多输出预测。模型在捕捉变量整体关联的同时，动态调整图结构和时间特征，适应不同发酵阶段的信息变化。</p><div class="flow"><div><b>学习整体关联</b><span>通过图结构获取模块与时间门控捕捉发酵过程的整体模式。</span></div><div><b>更新变量关系</b><span>结合 GCT 与自门控卷积，动态更新图结构。</span></div><div><b>筛选时间特征</b><span>通过门控时间卷积与自门控机制，自适应筛选预测信息。</span></div></div><div class="result-highlight"><div class="result-value">16.667%<span>MAE 降低</span></div><div><h3>在三个发酵数据集上验证</h3><p>在 Penisim、IndPenisim 和 DYG 上开展实验，相较于 MTGNN、Autoformer 等对比方法，论文报告平均绝对误差（MAE）降低 16.667%。</p></div></div><p>这项工作展示了将整体模式学习与动态信息筛选结合的价值，为生物发酵的时间序列建模提供了一种方法。</p></section>
<section id="people"><span class="eyebrow">People behind the work</span><h2>博士研究的第一步，感谢一路指导</h2><div class="mentor-note"><h3>刘兴高教授 · 从装置与过程理解变量关系</h3><p>我的导师刘兴高教授长期从事复杂系统建模与优化控制研究。他对夹套等过程装置的深入理解，以及对过程关系的形象化表征，引导我思考发酵变量之间的联系，也帮助我将交通网络的类比落到具体的发酵场景中。</p></div><p>这是我博士研究的第一个工作，非常感谢师兄 Qunshan He 的指导与帮助。</p></section>
<section id="journey"><span class="eyebrow">Research journey</span><h2>一次顺利而受益良多的发表经历</h2><p>这篇论文的发表过程很顺利。三位审稿人恰好都是图神经网络和时间序列领域的专家，他们专业的意见帮助我优化了实验部分的表达，让实验思路和结果更清楚，也让文章更容易被读者看懂。</p></section>`;}
function accessible(){return `<section id="origin"><span class="eyebrow">Where the idea began</span><h2>做完一个模型，开始追问数据从哪里来</h2><p>博士二年级，我接续 GWNet 的研究，开始思考一个更基础的问题。在上一项工作的推进过程中，我调查了许多青霉素、红霉素领域的研究，尤其关注产量预测。看得越多，越感到真实数据的获取是一道门槛：可公开获取的数据来源很少，很多工作依赖模拟数据开展研究。</p><p>这让我意识到，要让更多人进入这个领域，数据如何整理、如何保护、如何共享，同样值得投入研究。</p><p class="small"><a href="#work/gwnet">上一项工作：Gate-based GWNet</a></p><h3>一场跨方向的报告，带来了新的启发</h3><p>在一次学院报告中，我听到网络空间安全方向的同学介绍加密与解密。网络流量如何被保护并可信地传输，让我联想到生化过程中的数据：如果能通过适当的脱敏与保护，让数据具备共享条件，其他研究者是否就能沿着同一套流程开展研究？</p><div class="takeaway"><span class="tag">想法的起点</span><p>我想提供一套管线，让这个领域的研究有迹可循。</p></div><p>于是，我把研究重点放在从原始过程数据到可用于研究的数据这一整段流程上。我的视野也从青霉素和红霉素，逐步扩展到更广泛的、以批次数据呈现的生化过程。</p></section>
<section id="problem"><span class="eyebrow">The question</span><h2>Accessible：让更多人有条件开展研究</h2><p>题目中的 accessible，来自我对数据获取困难的切身体会。我希望研究者能够获得有用的数据，知道它经过了怎样的处理，并沿着清晰的流程继续建模、比较和验证。</p><div class="takeaway"><span class="tag">核心 insight</span><p>把数据保护与研究可用性一起考虑，才能为共享建立一条可实践的路径。</p></div><div class="analogy"><div><span class="eyebrow">研究中的障碍</span><h3>数据难获得，处理难衔接</h3><p>真实过程数据的共享受到限制，不同批次的数据还需要整理为适合建模的形式。</p></div><div><span class="eyebrow">希望提供的路径</span><h3>可复用的处理与保护管线</h3><p>将数据整理、隐私保护和过程关系表达衔接起来，降低开展后续研究的门槛。</p></div></div></section>
<section id="contribution"><span class="eyebrow">My contribution</span><h2>把研究所需的数据流程连接起来</h2><p>这项工作提供了面向批次过程的预处理与隐私保护管线，并配套发布数据与过程关系描述，让数据准备、共享和后续建模能够衔接。</p><div class="flow"><div><b>PPP · 数据预处理</b><span>批次分段、缺失值处理、任务相关的变量选择与批次归一化。</span></div><div><b>PPPP · 隐私保护</b><span>结合时序建模和领域知识生成数据，兼顾隐私保护与数据可用性。</span></div><div><b>研究资源</b><span>提供数据集、过程关系描述与实现代码，支持复用和后续验证。</span></div></div><p>项目仓库整理了红霉素、青霉素，以及蒸汽流量、食品加工和 Tennessee 过程等数据资源，也提供隐私评估、SKIM 评估与下游研究任务的代码入口。</p><div class="links"><a class="button" href="https://github.com/cynara517/Towards-Accessible-AI-Research-for-Complex-Batch-Biochemical-Processes">查看代码与数据</a></div></section>
<section id="journey"><span class="eyebrow">Research journey</span><h2>回应“方法学上没有创新”的质疑</h2><p>与第一篇工作的顺利发表不同，这项研究经历了不少不认可。投稿过程中，编辑更看重算法创新，而这套管线被认为偏向工程实现。我遇到的核心质疑是：方法学上没有创新。</p><p>后来，IEEE Transactions on Instrumentation and Measurement（TIM）的编辑给了这项工作继续接受评审和完善的机会。围绕管线的价值，我在多轮返修中查阅文献、补充论据，与审稿人反复沟通，逐步把这项工作的意义讲清楚。</p><p>感谢 TIM 编辑给予的机会，也感谢审稿过程中的讨论，让我进一步思考如何说明一套面向真实研究障碍的管线，能够为这个领域带来什么。</p></section>`;}
function ode(){return `<section id="origin"><span class="eyebrow">Where the idea began</span><h2>从微生物的生长节奏，重新理解发酵预测</h2><p>这是我的第三项工作。在前两项研究中，我一直关注如何利用数据预测发酵过程。随着研究深入，我越来越意识到，发酵中的微生物具有自己的生命周期、生长节奏和代谢活动，而我们希望获得的青霉素、红霉素等产物，正来自这些生命过程。</p><p>在投料量、温度和其他操作条件之外，微生物自身的状态及其演化同样影响着生产。这让我希望进一步理解：如何让预测模型利用这些生长与代谢规律？动力学为描述这种过程提供了语言，也让我把目光转向已有的常微分方程（ODE）模型。</p></section>
<section id="problem"><span class="eyebrow">The gap</span><h2>连接经典动力学与工业实际</h2><p>前人已经为青霉素、红霉素等发酵过程建立了动力学模型，用方程描述生长、底物消耗与产物形成之间的关系。这些工作提供了重要的机理基础，但已有模型与工业规模的实际生产之间，仍然存在距离。</p><p>面对真实生产数据，我希望探索如何让这些动力学结构与实际过程结合：既利用前人积累的机理知识，也让模型能够适应工业现场的变化。这成为这项工作的直接出发点。</p><div class="analogy"><div><span class="eyebrow">已有动力学</span><h3>理解生长与代谢</h3><p>以 ODE 表达过程变量如何相互影响、随时间演化。</p></div><div><span class="eyebrow">工业过程</span><h3>面对真实生产变化</h3><p>利用实际观测，探索机理知识如何参与预测。</p></div></div></section>
<section id="control"><span class="eyebrow">A connection to control theory</span><h2>世界模型，让我重新看见控制理论</h2><p>与此同时，世界模型的概念受到广泛关注。我去了解其中的思想，发现动作 a(t)、状态 s(t)，以及动作如何影响后续状态的描述，让我联想到控制理论中熟悉的控制输入、系统状态与动态响应。</p><p>这些联系也唤起了我对 PID 调节等反馈控制过程的理解：观测系统、施加调节，再根据系统的响应继续调整。世界模型中的这些表述，让我重新思考自己熟悉的控制理论，能够怎样作用于生物发酵的预测研究。</p><p>这进一步引出了一个问题：控制输入与过程状态之间的动态联系，能否通过 ODE 体现，并与数据驱动的学习过程结合？</p></section>
<section id="insight"><span class="eyebrow">Core insight</span><h2>让机理、控制与数据在预测中相遇</h2><p>微生物的生长与代谢提醒我关注过程自身的演化规律；经典动力学模型提供了描述这些规律的基础；世界模型则促使我重新思考控制输入、状态与反馈之间的联系。这几条思路最终汇聚到同一个研究动机：将 ODE 所表达的动态关系与工业数据结合，探索它们能为生物制药预测带来什么。</p><div class="takeaway"><span class="tag">研究动机</span><p>让描述生命过程的动力学知识，参与真实工业过程的预测。</p></div><p class="small"><a href="#work/gwnet">第一项工作 · 发酵变量关系与动态筛选</a><br><a href="#work/accessible">第二项工作 · 数据共享与研究可及性</a></p></section><section id="journey"><span class="eyebrow">Research journey</span><h2>一次重新寻找审稿人的发表历程</h2><p>这项工作横跨生物发酵、动力学建模与数据驱动预测，找到合适的审稿人并不容易。虽然一审收到了积极的评价，但在提交返修稿后，原审稿人均未能继续参与后续评审，论文的审稿过程也因此遇到了波折。</p><p>在主编 Salvador García-López 的帮助下，一审返修稿被重新送交三位新的审稿人。经过两轮大修和一轮小修，论文最终顺利发表。</p><p>特别感谢 Salvador García-López 在重新组织评审过程中的协调与支持，让这项交叉领域的研究得以继续推进；也感谢审稿人投入的时间与专业意见，帮助我们完成论文的修订。</p></section><section id="reflection"><span class="eyebrow">What I learned</span><h2>交叉研究，也需要跨越阅读的门槛</h2><p>漫长的审稿过程，也让我开始反思自己的写作。与此同时，我正在导师刘兴高教授和哈佛大学学者邓博士的共同指导下，开展另一项同样具有交叉性质的化学研究。两段经历放在一起，让我逐渐意识到：当时写论文时，我没有充分考虑不同领域学者的阅读难度。</p><p>一些内容写得过深，进入专业细节太快，却没有先为其他领域的读者铺好理解的路径。自己熟悉的概念和推理，对来自另一领域的研究者而言，未必同样直观。</p><div class="takeaway"><span class="tag">带到后续研究中的改变</span><p>写交叉领域的论文，也要为不同背景的读者建立理解的路径。</p></div><p>此后再写交叉性较强的文章，我都会有意识地考虑读者的知识背景：先讲清研究问题与必要概念，再逐步展开方法和细节。这成为这段研究与发表经历带给我的一项重要收获。</p></section>`;}
function safeguard(){return `<section id="origin"><span class="eyebrow">Where the idea began</span><h2>数据能够共享之后，如何判断它是否可信？</h2><p>这是从第二项工作 Accessible AI 延伸出来的一项探索。上一项研究中，我把网络安全领域带来的启发用于生化数据的保护与共享，希望让真实过程数据能够支持更多研究。这项工作沿着数据安全的问题，进一步走向发酵生产过程中的监测。</p><p>在共享场景中，我关注如何保护数据，同时保留它的研究价值。进入生产场景后，问题又向前推进了一步：如果传感器传来的数据被篡改，或者被一段历史数据替换，我们能否及时发现？一段看起来平滑、数值也处于常见范围内的曲线，是否仍然符合发酵过程正在经历的变化？</p><div class="analogy"><div><span class="eyebrow">Accessible AI</span><h3>让数据能够被使用</h3><p>连接预处理、隐私保护与共享，为后续研究提供可复用的数据基础。</p></div><div><span class="eyebrow">Bio-Process Safeguard</span><h3>判断数据是否值得信任</h3><p>把过程知识用于安全监测，检查观测数据是否符合发酵动力学。</p></div></div><p>这份延续也体现在实验基础上：本项研究使用了前一项工作提供的红霉素发酵数据，把同一份数据资源带入了工业控制系统安全的研究问题。</p><p class="small"><a href="#work/accessible">回到第二项工作 · Towards Accessible AI Research</a></p></section>
<section id="problem"><span class="eyebrow">Core insight</span><h2>看起来正常的数值，也可能偏离过程规律</h2><p>发酵过程中，“正常”会随着阶段而变化。微生物的生长和代谢改变着变量之间的关系，生产操作也会带来波动。因此，固定的一条报警线，很难同时适用于不同阶段；而经过设计的异常数据，也可能隐藏在看似合理的波动之中。</p><div class="takeaway"><span class="tag">核心 insight</span><p>判断数据是否可信，需要理解变量之间的动力学关系，以及这些关系随发酵阶段发生的变化。</p></div><p>这项工作把动力学模型作为检查数据的一种依据：从正常批次学习参数如何变化，再判断当前数据是否偏离相应阶段的正常范围。这样，安全监测就能利用发酵过程本身的知识。</p></section>
<section id="contribution"><span class="eyebrow">My contribution</span><h2>把动力学知识转化为安全监测的依据</h2><p>我们提出 Bio-Process Safeguard，将多智能体辅助的动力学变量映射与分阶段动态阈值结合，用于生物制药工业控制系统中的异常检测。</p><div class="flow"><div><b>连接传感器与动力学</b><span>Biodynamic Agents 辅助将监测变量对应到候选动力学方程，检查变量关系与参数的可辨识性。</span></div><div><b>学习不同阶段的正常范围</b><span>SWIFT 利用正常批次，通过分阶段滑动窗口重建动力学参数的动态阈值。</span></div><div><b>发现偏离过程的信号</b><span>结合残差分析与参数偏离，识别重放数据和虚假数据注入带来的异常。</span></div></div><p>在红霉素发酵场景中，我们围绕溶解氧与耗氧速率等变量建立动力学联系，并跟踪 α、kLa 和 γ 等参数在不同时间窗口中的变化。</p><div class="result-highlight"><div class="result-value">270<span>批红霉素发酵数据</span></div><div><h3>从正常过程重建，到攻击场景验证</h3><p>在 0–27 小时与 27–80 小时两个窗口中，正常轨迹重建的 R² 分别为 0.9065 和 0.8989，为后续异常监测提供了过程基线。</p></div></div><div class="analogy"><div><span class="eyebrow">Replay attacks</span><h3>识别 5 组构造的重放攻击</h3><p>将历史批次的数据用于替换目标批次的观测序列，五组测试中的攻击均被识别。跨阶段的参数变化帮助揭示了单个阶段中不易察觉的异常。</p></div><div><span class="eyebrow">False data injection</span><h3>在 30 个批次上评估虚假数据注入</h3><p>构造细微扰动，与 VAE 和纯动力学基线比较，展示了结合过程知识与动态阈值检测隐蔽异常的价值。</p></div></div><p>从整理和保护数据，到用数据理解生产过程的安全风险，这项工作让我把前一项研究建立的数据基础，进一步用于一个具体的安全监测问题。</p></section>`;}
function textileFigure(){return `<figure class="paper-figure textile-figure"><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7069695/" target="_blank" rel="noopener"><img src="assets/textile-science-advances-2020.jpg" width="440" height="271" alt="启发本科传感器项目的 Science Advances 研究：导电纱与尼龙纱织成柔性传感器，并缝入衣服以采集脉搏和呼吸信号。" loading="lazy"></a><figcaption>启发这项工作的织物传感研究 · Fan 等，<em>Science Advances</em>（2020），原论文图 1。图片：Wenjing Fan / 重庆大学；<a href="https://creativecommons.org/licenses/by-nc/4.0/">CC BY-NC 4.0</a>，未修改。</figcaption></figure>`;}
function undergraduateFeature(){return `<div class="section-head"><h2>本科探索 · 研究的起点</h2><p>织物传感器 · 数学建模 · 体育</p></div><section class="early-feature"><div><span class="eyebrow">Where curiosity took shape</span><h2>从看得见的实物，<br>种下交叉研究的种子。</h2><p>本科时，我在体育与数学建模中尝试不同的研究问题，也在周志浩老师的指导下，从一项 Science Advances 织物传感研究出发，参与睡眠检测系统的探索。实物与模拟，让不同学科的知识第一次在我面前连接起来。</p><a class="button" href="#undergraduate">走进本科阶段的五项工作</a></div>${textileFigure()}</section>`;}
function earlyPaper(id,description){const r=records.find(x=>x.id===id);return `<div class="early-paper" id="${id}"><div class="eyebrow">${r.year} · ${id==='hornets'?'CAMMIC':id==='face'?'ISPP':id==='exercise'?'Frontiers in Psychology':id==='marathon'?'Mathematical Problems in Engineering':'自动化应用'}</div><h3>${esc(r.short)}</h3><p>${description}</p><details><summary>论文信息与阅读</summary><p>${esc(r.title)}</p><p class="small">${esc(r.authors)}<br>${esc(r.venue)}</p><a href="${r.source||scholar}">${r.source?'阅读论文':'Google Scholar 论文入口'}</a></details></div>`;}
function undergraduate(){main.innerHTML=`<div class="page-top"><a class="small" href="#overview">研究概览 / 本科探索</a><div class="eyebrow early-eyebrow">Undergraduate explorations</div><h1>研究的起点，<br>是把好奇变成可以验证的问题。</h1><p class="lead">织物传感器、数学建模与体育——本科阶段的五项工作，记录了我走近研究、接触不同学科的最初尝试。</p></div><div class="detail-grid"><article><section id="sensors"><span class="eyebrow">Textile sensing · The first spark</span><h2>一项看得见实物的研究，种下了交叉学科的种子</h2><p>真正让我近距离接触前沿研究的，是本科时与<a href="https://faculty.cqupt.edu.cn/zhouzhihao/zh_CN/index.htm">周志浩老师</a>一起开展的织物传感器工作。当时的我刚开始探索研究，周老师也刚走上讲台。在他的引导下，我接触到他参与的一项 Science Advances 研究：把柔软、可水洗的织物做成传感器，用来采集脉搏与呼吸信号。</p><p>这是一项能够看到实物、也能够深入研究其原理的工作。纱线怎样形成传感结构，身体的微小变化怎样变成电信号，模拟又怎样帮助理解其中的过程——这些联系，让我开始看见材料、传感、建模与健康应用之间的交叉。</p>${textileFigure()}<p>沿着这项研究，我们进一步探索织物传感器在睡眠检测中的应用，形成了《基于织物传感器的睡眠检测系统》。其中既有传感器相关的工作，也涉及许多模拟。对当时的我而言，这是把论文中的想法、实物和模型联系起来的一次重要经历。</p>${earlyPaper('sleep','从前沿织物传感研究出发，将问题进一步落到睡眠检测系统。它是我本科阶段的一项研究，也是我接触交叉学科研究的起点。')}<div class="takeaway"><span class="tag">留给后续研究的启发</span><p>一个真实的器件，可以把材料、信号、模型与应用连接在一起。</p></div><div id="people" class="early-reflection"><span class="eyebrow">People & a shared beginning</span><h3>交叉研究的种子</h3><p>那段经历最珍贵的地方，是让我真正接触到什么是 CNS 级别的研究，体会到一项高水平工作背后需要付出多少精力，也亲身感受到交叉学科的魅力。</p><p>同期项目连续三届取得竞赛成果。我是第一任队长，我们团队共获得了中国国际“互联网+”大学生创新创业大赛全国铜奖 1 项、重庆市金奖 2 项，以及“挑战杯”全国大学生课外学术科技作品竞赛全国三等奖 1 项。</p><div class="award-list"><div><b>全国铜奖 × 1</b><span>中国国际“互联网+”大学生创新创业大赛</span></div><div><b>重庆市金奖 × 2</b><span>中国国际“互联网+”大学生创新创业大赛</span></div><div><b>全国三等奖 × 1</b><span>“挑战杯”全国大学生课外学术科技作品竞赛</span></div></div><p>大创与竞赛伴随着这些探索，也让研究有机会走向更具体的应用。对我来说，这段经历播下了交叉研究的种子，让我愿意继续走近陌生领域，寻找能够把不同知识连接起来的问题。</p></div></section>
<section id="modeling"><span class="eyebrow">Mathematical modeling · Two studies</span><h2>数学建模：从现实对象，到算法表达</h2><p>数学建模相关的两项工作，分别围绕亚洲大黄蜂的轨迹追踪与人脸识别展开。它们记录了我本科阶段接触机器学习、尝试用算法描述具体问题的过程。</p>${earlyPaper('hornets','围绕亚洲大黄蜂的轨迹追踪问题，研究使用 SVM 与 BA-SVM 方法，将实际对象的追踪问题带入数学建模与算法分析。')}${earlyPaper('face','这项工作将开运算与 Softmax-BP 方法用于人脸识别，把图像处理与分类模型连接起来，探索从图像信息到识别结果的实现路径。')}</section>
<section id="sports"><span class="eyebrow">Sports research · Two studies</span><h2>体育研究：从赛事评价，到个体康复</h2><p>本科阶段，我参与了两项体育相关研究。一项关注如何评价一场大型赛事，另一项关注退役运动员的身体功能与运动恐惧。两个问题分别从赛事和个体出发，把观察转化为可以分析的指标。</p>${earlyPaper('marathon','围绕重庆国际马拉松，我建立了基于层次分析法（AHP）的赛事评价体系，结合文献、实地调查与专家咨询，将赛事的综合影响转化为分层指标及其权重。体系包含 5 项一级指标、13 项二级指标和 58 项三级指标，覆盖政治、经济、文化、社会与环境等维度。')}<div class="mentor-note"><h3>在真实数据中受到磨砺</h3><p>建立这套 AHP 体系的过程，也让我体会到处理真实数据的艰难。把方法落到实际数据上，需要付出的精力远超当时的预想，其中的痛苦与挫折让我受到磨砺，也推动了我的成长。我逐渐学会以更耐心、更严谨的态度面对数据，把每一步分析做扎实。</p></div>${earlyPaper('exercise','这项个案研究跟踪了一名有陈旧性髌骨骨折的退役运动员，在 12 周运动干预中观察膝关节功能、疼痛与运动恐惧的变化。个案的膝关节功能评分由 76 提高到 95，运动恐惧评分由 50 降至 34。它把身体功能与心理感受放在一起考察，记录了这名运动员的康复过程。')}</section>
<section id="reading"><h2>延伸阅读</h2><p><a href="https://doi.org/10.1126/sciadv.aay2840">启发传感器项目的研究 · Machine-knitted washable sensor array textile for precise epidermal physiological signal monitoring</a></p><p><a href="https://faculty.cqupt.edu.cn/zhouzhihao/zh_CN/index.htm">周志浩老师主页</a></p></section></article><aside class="facts"><span class="eyebrow">Early research</span><dl><dt>研究时期</dt><dd>本科阶段</dd><dt>成果年份</dt><dd>2021–2022</dd><dt>共同的起点</dt><dd>把现实问题转化为研究，连接不同学科的知识。</dd></dl><nav aria-label="页内目录"><a href="#undergraduate/sensors">传感器与交叉研究 · 1 项</a><a href="#undergraduate/modeling">数学建模相关研究 · 2 项</a><a href="#undergraduate/sports">体育相关研究 · 2 项</a><a href="#undergraduate/reading">延伸阅读</a></nav></aside></div>`;}
function about(){main.innerHTML=`<div class="page-top"><div class="eyebrow">About & collaboration</div><h1>研究，也是一段合作历程。</h1></div><div class="about-block"><h2>Shifan Chen</h2><p class="muted">我在浙江大学开展生化过程与人工智能相关研究，关注过程建模、研究数据的可及性，以及不同学科之间的联系。</p><div class="links"><a class="button" href="${scholar}">Google Scholar</a><a class="button" href="https://github.com/cynara517">GitHub</a><a class="button" href="../chemwatch.html">ChemWatch</a></div><h2>把帮助放回具体课题</h2><p class="muted">每项研究档案都保留导师与合作者的贡献位置，记录问题定义、方法设计、数据资源、验证和写作中发生的协作。</p><p><a href="#work/gwnet/people">阅读 GWNet 的指导与合作故事</a></p></div>`;}
function route(){const [page,id,anchor]=(location.hash.slice(1)||'overview').split('/');const record=page==='work'?records.find(r=>r.id===id):null;const isEarly=page==='undergraduate'||!!record?.earlyGroup;if(page==='work')detail(id);else if(page==='undergraduate')undergraduate();else if(page==='publications')publications();else if(page==='about')about();else overview();document.title=isEarly?'本科探索 · 研究的起点 · Shifan Chen':page==='work'?`${record?.title||'研究档案'} · Shifan Chen`:'Shifan Chen · Research & the work behind it';document.querySelectorAll('.section-nav a').forEach(a=>a.setAttribute('aria-current',a.hash===`#${isEarly?'undergraduate':page}`?'page':'false'));const target=page==='undergraduate'?id:record?.earlyGroup?(anchor||record.earlyGroup):anchor;window.localizePapers?.();if(target)document.getElementById(target)?.scrollIntoView();else window.scrollTo(0,0);}
window.addEventListener('hashchange',route);document.addEventListener('chemwatch-language',()=>{route();});route();
